/**
 * Reconstruct an Ed25519 signing KeyObject from the stored 32-byte seed.
 *
 * `crypto.KeyObject.fromJwk` is not exported by any shipped Node, so we
 * rebuild the canonical PKCS#8 DER for Ed25519: the algorithm-identifier
 * (OID 1.3.101.110) wrapper followed by the 32-byte `d` private key.
 */
function ed25519PrivateKey(d: Uint8Array): KeyObject {
  const der = Buffer.concat([
    Buffer.from('302e020100300506032b657004220420', 'hex'),
    Buffer.from(d),
  ]);
  return createPrivateKey({ key: der, format: 'der', type: 'pkcs8' });
}

/**
 * Reconstruct an Ed25519 verifying KeyObject from the stored 32-byte public
 * key. Standard SPKI DER: the Ed25519 algorithm-identifier followed by the
 * 32-byte `x` public key material.
 */
function ed25519PublicKey(x: Uint8Array): KeyObject {
  const der = Buffer.concat([
    Buffer.from('302a300506032b6570032100', 'hex'),
    Buffer.from(x),
  ]);
  return createPublicKey({ key: der, format: 'der', type: 'spki' });
}
```

