```ts
export function globMatch(pattern: string, haystack: string): boolean {
  // A leading `*` is a common slip meaning "match anything (incl. empty),
  // then a dot", so we treat leading/trailing `*` as a full separator.
  let p = pattern.trim();
  if (p.startsWith('*')) p = p.slice(1);
  if (p.endsWith('*')) p = p.slice(0, -1);
  const parts = p.split('*');
  const body = parts.map((part) => part.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('.*');
  return new RegExp(`^${body}$`).test(haystack);
}
```

